const { JSDOM, ResourceLoader } = require("jsdom");
const axe = require("axe-core");

(async () => {
  const dir = __dirname;
  const html = fs.readFileSync(path.join(dir, "index.html"), "utf8");

  const dom = new JSDOM(html, {
    url: "file://" + dir + "/",
    runScripts: "dangerously",
    resources: new ResourceLoader(),
    pretendToBeVisual: true,
  });
  const { window } = dom;

  // Inject CSS so axe can evaluate contrast/visibility
  const css = fs.readFileSync(path.join(dir, "styles.css"), "utf8");
  const style = window.document.createElement("style");
  style.textContent = css;
  window.document.head.appendChild(style);

  // Load React/ReactDOM/Babel from node_modules-ish: use UMD copies via CDN files we can fetch... use local loader.
  const load = (p) => fs.readFileSync(require.resolve(p), "utf8");
  const inject = (code) => {
    const s = window.document.createElement("script");
    s.textContent = code;
    window.document.head.appendChild(s);
  };

  inject(load("react/umd/react.development.js"));
  inject(load("react-dom/umd/react-dom.development.js"));

  // Transform app.js with @babel/standalone
  const babel = require("@babel/standalone");
  const appSrc = fs.readFileSync(path.join(dir, "app.js"), "utf8");
  const compiled = babel.transform(appSrc, { presets: ["react"] }).code;
  inject(compiled);

  await new Promise(r => setTimeout(r, 200));

  // axe
  inject(fs.readFileSync(require.resolve("axe-core/axe.min.js"), "utf8"));

  const runAxe = async (label) => {
    const results = await window.axe.run(window.document, {
      runOnly: { type: "tag", values: ["wcag2a","wcag2aa","wcag21a","wcag21aa","wcag22aa","best-practice"] },
    });
    console.log(`\n=== axe (${label}) — violations: ${results.violations.length} ===`);
    for (const v of results.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      for (const n of v.nodes) console.log(`    ${n.target.join(" ")}`);
    }
    return results.violations.length;
  };

  let total = await runAxe("initial");

  // simulate invalid submit
  const btn = window.document.querySelector('button[type="submit"]');
  btn.click();
  await new Promise(r => setTimeout(r, 200));
  total += await runAxe("after invalid submit");

  process.exit(total === 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(2); });

